      'clamp)', () async {
    tools.handlers['gitlab_list_project_jobs']!({
      'workspace': 'g',
      'repository': 'r',
      'per_page': '250',
      'page': '3',
    });
    final requests = await requestLog();
    expect(requests.single['path'],
        '/api/v4/projects/g%2Fr/jobs?per_page=100&page=3');
